import React, { useEffect, useRef } from 'react';

const PREMIUM_COLORS = [
  'rgba(245, 158, 11, 0.65)', // Amber
  'rgba(59, 130, 246, 0.65)',  // Blue
  'rgba(16, 185, 129, 0.65)', // Emerald
  'rgba(139, 92, 246, 0.65)',  // Purple
  'rgba(236, 72, 153, 0.65)',  // Pink
];

const AntigravityCanvas = ({
  className = '',
  particleCount = 140,
  colors = PREMIUM_COLORS,
  forceRadius = 140,
  springStrength = 0.03,
  damping = 0.86,
  repulsionStrength = 15,
}) => {
  const canvasRef = useRef(null);
  const mouseRef = useRef({ x: undefined, y: undefined });
  const particlesRef = useRef([]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    let animationFrameId;

    const initCanvasSize = () => {
      // Use offset width/height of the actual styled canvas element
      const width = canvas.offsetWidth || window.innerWidth;
      const height = canvas.offsetHeight || window.innerHeight;
      
      canvas.width = width;
      canvas.height = height;
      
      const particles = [];
      const cols = Math.floor(Math.sqrt(particleCount * (width / height))) || 1;
      const rows = Math.floor(particleCount / cols) || 1;
      
      const cellWidth = width / cols;
      const cellHeight = height / rows;

      for (let i = 0; i < cols; i++) {
        for (let j = 0; j < rows; j++) {
          const posX = i * cellWidth + Math.random() * (cellWidth * 0.7) + cellWidth * 0.15;
          const posY = j * cellHeight + Math.random() * (cellHeight * 0.7) + cellHeight * 0.15;
          
          particles.push({
            x: posX,
            y: posY,
            curX: posX,
            curY: posY,
            vx: 0,
            vy: 0,
            size: Math.random() * 2 + 1, // 1px to 3px
            color: colors[Math.floor(Math.random() * colors.length)],
            density: Math.random() * 15 + 5,
          });
        }
      }
      particlesRef.current = particles;
    };

    initCanvasSize();

    // Track mouse coordinates GLOBALLY on window to avoid layering blocking issues
    const handleMouseMove = (e) => {
      const rect = canvas.getBoundingClientRect();
      mouseRef.current = {
        x: e.clientX - rect.left,
        y: e.clientY - rect.top,
      };
    };

    const handleMouseLeave = () => {
      mouseRef.current = { x: undefined, y: undefined };
    };

    const handleResize = () => {
      initCanvasSize();
    };

    window.addEventListener('resize', handleResize);
    window.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseleave', handleMouseLeave);

    const animate = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      const mouse = mouseRef.current;
      const particles = particlesRef.current;

      for (let i = 0; i < particles.length; i++) {
        const p = particles[i];

        if (mouse.x !== undefined && mouse.y !== undefined) {
          const dx = mouse.x - p.curX;
          const dy = mouse.y - p.curY;
          const distance = Math.sqrt(dx * dx + dy * dy);

          if (distance < forceRadius) {
            const force = (forceRadius - distance) / forceRadius; // 0 to 1 scaling
            const dirX = dx / (distance || 1);
            const dirY = dy / (distance || 1);

            const push = force * repulsionStrength * (12 / p.density);
            p.vx -= dirX * push;
            p.vy -= dirY * push;
          }
        }

        const homeDx = p.x - p.curX;
        const homeDy = p.y - p.curY;

        p.vx += homeDx * springStrength;
        p.vy += homeDy * springStrength;

        p.vx *= damping;
        p.vy *= damping;

        p.curX += p.vx;
        p.curY += p.vy;

        ctx.beginPath();
        ctx.arc(p.curX, p.curY, p.size, 0, Math.PI * 2);
        ctx.fillStyle = p.color;
        ctx.fill();
      }

      animationFrameId = requestAnimationFrame(animate);
    };

    animate();

    return () => {
      cancelAnimationFrame(animationFrameId);
      window.removeEventListener('resize', handleResize);
      window.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseleave', handleMouseLeave);
    };
  }, [colors, particleCount, forceRadius, springStrength, damping, repulsionStrength]);

  return (
    <canvas
      ref={canvasRef}
      className={`absolute inset-0 w-full h-full pointer-events-none mix-blend-screen z-0 ${className}`}
      style={{ display: 'block' }}
    />
  );
};

export default AntigravityCanvas;
